def subtract(a, b):
    # Filter out empty intervals and sort by start position
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            # Overlapping or touching - merge
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    result = []

    # Process each interval in a
    for a_start, a_end in a_intervals:
        current_start = a_start

        # Subtract each b interval from current interval
        for b_start, b_end in merged_b:
            # If b_end <= current_start, b doesn't affect current interval
            if b_end <= current_start:
                continue
            # If b_start >= a_end, b is completely after current interval
            if b_start >= a_end:
                break

            # b overlaps with [current_start, a_end)
            if b_start > current_start:
                # Add the part before b
                result.append([current_start, b_start])

            # Move current_start past b
            current_start = max(current_start, b_end)

        # Add remaining part if any
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge adjacent intervals that touch
    final_result = []
    for start, end in result:
        if final_result and start == final_result[-1][1]:
            # Touching - merge
            final_result[-1][1] = end
        else:
            final_result.append([start, end])

    return final_result

